#include <iostream>
#include <vector>
#include <string>
using namespace std;

vector<int> parent, sizes;

int findRoot(int x) {
    while (parent[x] != x) {
        parent[x] = parent[parent[x]];
        x = parent[x];
    }
    return x;
}

bool unite(int a, int b) {
    a = findRoot(a);
    b = findRoot(b);
    if (a == b) return false;
    if (sizes[a] < sizes[b]) swap(a, b);
    parent[b] = a;
    sizes[a] += sizes[b];
    return true;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    long long t;
    long long q;
    cin >> n >> t >> q;
    vector<vector<long long>> qs(q, vector<long long>(2));
    for (int i = 0; i < q; i++) {
        for (int j = 0; j < 2; j++) {
            cin >> qs[i][j];
        }
    }

    parent.resize(n + 1);
    sizes.assign(n + 1, 1);
    for (int v = 0; v <= n; v++) parent[v] = v;
    for (long long d = t + 1; d <= n; d++) {
        for (long long multiple = 2 * d; multiple <= n; multiple += d) unite((int)d, (int)multiple);
    }
    for (const vector<long long>& query : qs) cout << (findRoot((int)query[0]) == findRoot((int)query[1]) ? "yes" : "no") << "\n";

    return 0;
}

