import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    static int[] parent;
    static int[] sizes;

    static int findRoot(int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }

    static boolean unite(int a, int b) {
        a = findRoot(a);
        b = findRoot(b);
        if (a == b) return false;
        if (sizes[a] < sizes[b]) {
            int t = a;
            a = b;
            b = t;
        }
        parent[b] = a;
        sizes[a] += sizes[b];
        return true;
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long t = Long.parseLong(next());
        long q = Long.parseLong(next());
        long[][] qs = new long[(int) q][2];
        for (int i = 0; i < qs.length; i++) {
            for (int j = 0; j < qs[i].length; j++) {
                qs[i][j] = Long.parseLong(next());
            }
        }

        int cities = (int) n;
        parent = new int[cities + 1];
        sizes = new int[cities + 1];
        for (int v = 0; v <= cities; v++) {
            parent[v] = v;
            sizes[v] = 1;
        }
        for (long d = t + 1; d <= n; d++) {
            for (long multiple = 2 * d; multiple <= n; multiple += d) unite((int) d, (int) multiple);
        }
        StringBuilder out = new StringBuilder();
        for (long[] query : qs) out.append(findRoot((int) query[0]) == findRoot((int) query[1]) ? "yes" : "no").append("\n");
        System.out.print(out);
    }
}
